    candidate_graph = identity_ledger.query_probabilistic(touchpoint.soft_signals)
    link_entropy = compute_cluster_entropy(candidate_graph, touchpoint.context)
    # 5. Fail closed: accepting blind reach is mathematically safer than corrupting the graph with false merges
    if link_entropy > ACCEPTABLE_NOISE_CEILING: return EphemeralProfile(touchpoint)
    return ScopedCohortToken(candidate_graph.best_match, error_bound=link_entropy)

